local backing = { score = 10 }
local proxy = setmetatable({}, {
    __index = backing,
    __newindex = function(_, key, value)
        if key ~= "score" or type(value) ~= "number" then
            error("unsupported field or value")
        end
        backing[key] = value
    end,
})
proxy.score = 12
print(proxy.score)
-- A Lua proxy is not an OS-enforced sandbox.

